import { Book } from "@/lib/types";

export const daniel: Book = {
  id: "daniel",
  name: "Daniel",
  shortName: "Dan",
  testament: "old",
  introduction: `Gottes Herrschaft setzt sich durch\nDaniel wurde als 14-jährige Geisel schon im Jahr 605 v.Chr. nach Babylon verschleppt. Dort bekam er eine dreijährige Ausbildung zum Hofbeamten des Königs und tat sich bald durch seine große Weisheit hervor. Ungefähr 70 Jahre lang bezeugte er den babylonischen Königen die Erhabenheit Gottes über alle Völker, den niemand an der Ausführung seiner Pläne hindern kann.\nVon der Bibelkritik wird die Verfasserschaft Daniels mit verschiedenen Argumenten bestritten, die aber alle widerlegbar sind. Das Hauptargument der Kritik ist letztlich die Leugnung echter Prophetie, denn die Vorhersagen in Kapitel 8 und 11 haben sich schon zwischen dem vierten und dem zweiten Jahrhundert v.Chr. bis in Einzelheiten genau erfüllt. Sie weisen aber noch weit darüber hinaus bis in die Zeit unseres Herrn Jesus Christus und seines Wiederkommens.\n**Das Buch Daniel** enthält von Kapitel 1-6 die Danielgeschichte, von 7-12 die Danielgesichte (Weissagungen).\n****Wie Gottes Macht sich im Leben von vier Freunden beweist und wie Gottes Reich sich in Zukunft durchsetzen wird.****`,
  chapters: [
    { number: 1, verses: [
      { number: 1, text: "Im dritten Regierungsjahr* des Königs Jojakim von Juda zog der babylonische König Nebukadnezzar vor Jerusalem und bedrängte die Stadt*.", heading: "1-6: Die Danielgeschichte – Wie Gottes Herrschaft sich an Menschen beweist\nDaniel am babylonischen Hof", footnotes: ["Im dritten Regierungsjahr = 605 v.Chr. Nach jüdischer Zählung war dies das vierte Jahr Jojakims (siehe Jeremia 25,1; 46,2). In Babylon zählte man die Regierungsjahre erst ab dem nächsten vollen Jahr. Daniel verwendete also die babylonische Zählweise.", "bedrängte die Stadt. Das geschah während eines Feldzugs zur Eroberung von Syrien und Israel. Am 15. August 605 v.Chr. starb Nabopolassar, der Vater Nebukadnezzars. Daraufhin eilte der Kronprinz mit kleinem Gefolge zurück, um sich die Herrschaft zu sichern. Nebukadnezzar wurde am 7. September inthronisiert und bestimmte 43 Jahre lang die Geschicke des Orients."] },
      { number: 2, text: "Der Herr gab König Jojakim in die Gewalt Nebukadnezzars und ließ auch einen Teil der Tempelgeräte in seine Hand fallen. Nebukadnezzar brachte sie ins Land Schinar* und ließ sie in der Schatzkammer im Tempel seines Gottes aufbewahren.", footnotes: ["Land Schinar. Das meint die Ebene Babyloniens, wo die Menschen einst in grenzenloser Überheblichkeit den babylonischen Turm gebaut hatten (siehe 1. Mose 11,1-9)."] },
      { number: 3, text: "Seinem obersten Hofbeamten Aschpenas befahl er, einige junge Israeliten aus dem Königshaus und den vornehmen Familien auszusuchen." },
      { number: 4, text: "\"Die jungen Männer müssen gesund sein und gut aussehen\", sagte er. \"Sie müssen gut unterrichtet, klug und begabt sein, denn sie sollen in den Dienst am Königshof treten. Und dann sollen sie in der Sprache und Literatur der Chaldäer* unterwiesen werden.\"", footnotes: ["Die Chaldäer waren aramäisch (syrisch) sprechende Semiten aus dem südlichen Zweistromland."] },
      { number: 5, text: "Drei Jahre lang sollten die jungen Leute ausgebildet werden und danach in den Dienst des Königs treten. Der König ordnete an, dass sie von der königlichen Tafel mit Speise und Wein versorgt würden." },
      { number: 6, text: "Zu den jungen Juden, die ausgesucht wurden, gehörten auch Daniel, Hananja, Mischaël und Asarja." },
      { number: 7, text: "Aschpenas gab ihnen babylonische Namen: Daniel nannte er Beltschazzar, Hananja Schadrach, Mischaël Meschach und Asarja Abed-Nego.*", footnotes: ["... Abed-Nego. Die Namensänderung drückte einerseits die neue Herrschaft über die jungen Leute aus und stellte sie andererseits in Beziehung zu den babylonischen Göttern. Daniel = Gott ist Richter – Beltschazzar = Bel (Marduk) schütze sein Leben; Hananja = Jahwe ist gnädig – Schadrach = Befehl Akus (sumerischer Mondgott); Mischaël = Wer ist wie Gott? – Meschach = Wer ist wie Aku?; Asarja = Jahwe hilft – Abed-Nego = Diener Negos (Nabus)."] },
      { number: 8, text: "Aber Daniel war fest entschlossen, sich nicht mit der Tafelkost des Königs zu verunreinigen*. Deshalb bat er Aschpenas, dass er nicht gezwungen würde, sich vor Gott unrein zu machen.", footnotes: ["Er würde sich Gott gegenüber verunreinigen, weil die Speisen und Getränke immer den babylonischen Göttern geweiht wurden."] },
      { number: 9, text: "Gott sorgte dafür, dass der oberste Hofbeamte Verständnis für ihn zeigte." },
      { number: 10, text: "Allerdings sagte er zu Daniel: \"Ich habe Bedenken wegen meinem Herrn, dem König, denn er hat selbst bestimmt, was ihr essen und trinken sollt. Wenn er merkt, dass ihr schlechter ausseht als die anderen jungen Leute, lässt er mir den Kopf abschlagen.\"" },
      { number: 11, text: "Dann wandte sich Daniel an den Aufseher, den Aschpenas über ihn, Hananja, Mischaël und Asarja eingesetzt hatte:" },
      { number: 12, text: "\"Versuch es doch einmal zehn Tage lang mit uns! Gib uns nur Gemüse und Wasser" },
      { number: 13, text: "und vergleiche dann unser Aussehen mit dem der anderen jungen Leute, die von der königlichen Tafel versorgt werden. Triff deine Entscheidung nach dem, was du dabei feststellst!\"" },
      { number: 14, text: "Der Aufseher war einverstanden und machte den zehntägigen Versuch mit ihnen." },
      { number: 15, text: "Nach Ablauf der Frist sahen die jungen Männer sogar gesünder und kräftiger aus als die anderen." },
      { number: 16, text: "Von da an gab ihnen der Aufseher immer Gemüse. Sie mussten nichts von der Tafelkost des Königs essen." },
      { number: 17, text: "Gott schenkte diesen vier jungen Männern Kenntnis und Verständnis für jede Schrift. Auf allen Wissensgebieten kannten sie sich aus, und Daniel konnte darüber hinaus Visionen und alle Arten von Träumen verstehen." },
      { number: 18, text: "Am Ende der Ausbildungszeit befahl der König, die jungen Leute zu ihm zu bringen. Der oberste Hofbeamte stellte sie Nebukadnezzar vor," },
      { number: 19, text: "und der König redete mit ihnen. Dabei stellte sich heraus, dass Daniel, Hananja, Mischaël und Asarja alle anderen in den Schatten stellten. Sie wurden in den königlichen Dienst aufgenommen." },
      { number: 20, text: "Und immer, wenn der König auf ein sicheres Urteil angewiesen war und ihren Rat suchte, fand er sie seinen Magiern und Geisterbeschwörern zehnfach überlegen." },
      { number: 21, text: "Daniel blieb bis zum ersten Regierungsjahr des Königs Kyrus* in königlichen Diensten.", footnotes: ["... des Königs Kyrus. Das heißt: noch 67 Jahre bis 538 v.Chr."] },
    ] },
    { number: 2, verses: [
      { number: 1, text: "Im zweiten Jahr seiner Regierung* hatte Nebukadnezzar einen Traum, der ihn so beunruhigte, dass es mit seinem Schlaf vorbei war.", heading: "Nebukadnezzars Traum", footnotes: ["... Regierung. Das war im Jahr 603/2 v.Chr. Daniel hatte seine Ausbildung also fast abgeschlossen."] },
      { number: 2, text: "Da ließ der König die Magier, die Geisterbeschwörer, die Orakelpriester und die Astrologen zu sich rufen. Sie sollten ihm Aufschluss über seinen Traum geben. Als sie sich beim König versammelt hatten," },
      { number: 3, text: "sagte der König zu ihnen: \"Ich habe einen Traum gehabt, der mich sehr beunruhigt. Ich will wissen, was es damit auf sich hat.\"*", footnotes: ["... auf sich hat. Man kann den Grundtext auch so verstehen, dass der König den Traum wirklich vergessen hatte, was als besonders unheilvolles Zeichen galt."] },
      { number: 4, text: "Da sagten die Astrologen zum König auf Aramäisch*: \"Der König lebe ewig! Möge er seinen Dienern den Traum erzählen, dann wollen wir ihn deuten.\"", footnotes: ["Aramäisch. Die aus verschiedenen Völkern stammenden Astrologen verständigten sich auf Aramäisch. Auch das Buch Daniel ist von hier an bis Kapitel 7,28 nicht mehr in hebräischer, sondern in aramäischer Sprache verfasst."] },
      { number: 5, text: "Doch der König erwiderte: \"Nein, ich habe unwiderruflich entschieden, dass ihr mir auch den Traum mitteilen müsst, nicht nur seine Deutung. Wenn ihr das nicht tut, lasse ich euch in Stücke hauen und eure Häuser in Schutt und Asche legen." },
      { number: 6, text: "Sagt mir also den Traum und die Deutung dazu! Dann werde ich euch reich beschenken und euch hohe Ehre erweisen. Also los, sagt es mir!\"" },
      { number: 7, text: "Die Berater sagten noch einmal: \"Der König möge seinen Dienern den Traum erzählen, dann werden wir ihn deuten!\"" },
      { number: 8, text: "Da fuhr der König sie an: \"Ihr macht nur Ausflüchte und wollt Zeit gewinnen! Ihr habt genau verstanden, wie ich die Sache entschieden habe!" },
      { number: 9, text: "Wenn ihr mir nicht sagt, was ich geträumt habe, lasse ich das Urteil vollstrecken. Ihr habt euch verabredet, mir weiter nichts als Lug und Trug aufzutischen, bis die Zeit sich geändert hat.* Darum sagt mir den Traum! Dann weiß ich auch, ob ihr ihn überhaupt deuten könnt.\"", footnotes: ["bis die Zeit sich geändert hat. Damit verdächtigte er sie wahrscheinlich, Umsturzpläne zu verfolgen."] },
      { number: 10, text: "Da entgegneten die Astrologen: \"Kein Mensch auf der ganzen Welt kann tun, was der König verlangt! Und noch nie hat ein König von irgendeinem Magier, Geisterbeschwörer oder Astrologen so etwas verlangt." },
      { number: 11, text: "Was du uns zumutest, ist für Menschen unmöglich! Nur die Götter könnten es dem König offenbaren; aber sie wohnen nicht unter den Menschen.\"" },
      { number: 12, text: "Über diese Antwort wurde der König so wütend, dass er befahl, alle Weisen von Babel töten zu lassen." },
      { number: 13, text: "Und tatsächlich erging der Befehl: \"Die Weisen sollen getötet werden!\" Auch Daniel und seine Freunde waren davon betroffen. Man suchte sie, um sie töten zu lassen." },
      { number: 14, text: "Als Arjoch, der Befehlshaber der königlichen Leibwache, zu Daniel kam, stellte dieser ihm eine gut überlegte kluge Frage:" },
      { number: 15, text: "\"Warum hat der König diesen strengen Befehl gegeben?\" Arjoch berichtete ihm, wie es dazu gekommen war." },
      { number: 16, text: "Sofort ging Daniel zum König und bat sich eine Frist aus, um ihm die Deutung verkünden zu können." },
      { number: 17, text: "Dann ging er in sein Haus und berichtete es Hananja, Mischaël und Asarja." },
      { number: 18, text: "Sie sollten den Gott des Himmels um Gnade bitten, damit er und seine Freunde nicht mit den anderen Weisen umkämen." },
      { number: 19, text: "Darauf wurde ihm das Geheimnis in einer nächtlichen Vision enthüllt, und Daniel rühmte den Gott des Himmels." },
      { number: 20, text: "Er sagte: \"In alle Ewigkeit soll der Name Gottes gepriesen werden! Ihm gehören Weisheit und Macht." },
      { number: 21, text: "Er bestimmt den Wechsel der Zeiten, er setzt Könige ab und setzt Könige ein. Er gibt den Weisen ihre Weisheit und den Klugen ihren Verstand." },
      { number: 22, text: "Er offenbart auch das, was tief verborgen ist, und weiß, was in der Finsternis wohnt. Doch ihn selbst umstrahlt das Licht." },
      { number: 23, text: "Dich, Gott meiner Väter, rühme und lobe ich! Denn du hast mir Weisheit und Kraft geschenkt. Und jetzt hast du mich wissen lassen, was wir von dir erbaten. Du hast uns den Traum des Königs enthüllt.\"" },
      { number: 24, text: "Daraufhin ging Daniel zu Arjoch, der den Befehl hatte, die Weisen Babylons zu töten, und sagte zu ihm: \"Bring die Weisen Babylons nicht um! Führ mich zum König, damit ich ihm die Deutung angeben kann!\"" },
      { number: 25, text: "Arjoch brachte ihn sofort zum König und meldete: \"Ich habe unter den Deportierten aus Judäa einen Mann gefunden, der dem König die Deutung seines Traumes mitteilen kann.\"" },
      { number: 26, text: "Der König fragte Daniel, der jetzt Beltschazzar genannt wurde: \"Kannst du mir wirklich sagen, was ich im Traum gesehen habe, und mir mitteilen, was es bedeutet?\"" },
      { number: 27, text: "Daniel begann vor dem König zu sprechen: \"Das Geheimnis, nach dem der König verlangt\", sagte er, \"können Magier, Geisterbeschwörer, Orakelpriester und Astrologen dem König nicht verkündigen." },
      { number: 28, text: "Aber es gibt einen Gott im Himmel, der das Verborgene enthüllt. Er wollte dir zeigen, König Nebukadnezzar, was am Ende der von Gott bestimmten Zeit geschehen wird. Dein Traum, die Schau, die du auf deinem Lager hattest, war folgende:" },
      { number: 29, text: "Auf deinem Lager kamen dir, König, Gedanken über das, was künftig geschehen wird. Und der, der die Geheimnisse offenbart, hat dich wissen lassen, was geschehen wird." },
      { number: 30, text: "Auch mir ist dieses Geheimnis nicht offenbar gemacht worden, weil ich weiser als alle anderen Menschen wäre, sondern nur, damit der König die Deutung erfährt und die Gedanken seines Herzens erfasst." },
      { number: 31, text: "Du, König, sahst auf einmal eine gewaltige Statue vor dir. Es war eine furchterregende Erscheinung, denn sie war riesig groß und ihr Glanz blendete." },
      { number: 32, text: "Der Kopf der Statue bestand aus gediegenem Gold. Brust und Arme waren aus Silber, Bauch und Lenden aus Bronze," },
      { number: 33, text: "die Beine aus Eisen und ihre Füße zum Teil aus Eisen und zum Teil aus Ton." },
      { number: 34, text: "Während du sie noch anschautest, brach auf einmal ohne Zutun einer Menschenhand ein Stein los. Er traf die Füße der Statue, die aus Eisen und Ton bestanden, und zerschmetterte sie." },
      { number: 35, text: "Da wurden Eisen und Ton, Bronze, Silber und Gold miteinander zu Staub zermalmt. Auf einmal waren sie wie die Spreu auf dem Dreschplatz im Sommer. Der Wind trug sie fort, und es war keine Spur mehr davon übrig. Aber der Stein, der die Statue zerschlagen hatte, wuchs zu einem riesigen Berg, der die ganze Erde ausfüllte." },
      { number: 36, text: "Das war der Traum. Und nun wollen wir dem König sagen, was er bedeutet." },
      { number: 37, text: "Du, König, bist der König der Könige. Der Gott des Himmels hat dir Herrschaft und Macht, Stärke und Ehre geschenkt." },
      { number: 38, text: "Und überall, wo Menschen wohnen, hat er dir auch die Landtiere und die Vögel in die Hand gegeben und dich zum Herrscher über sie alle eingesetzt. Du bist der Kopf aus Gold.*", footnotes: ["Kopf aus Gold. Gemeint ist das babylonische Weltreich."] },
      { number: 39, text: "Auf dein Reich wird ein anderes folgen, das geringer als deins sein wird.* Dann folgt ein drittes Reich – das aus Bronze –, das über die ganze Erde herrschen wird.*", footnotes: ["geringer als deins sein wird. Das Reich der Meder und Perser, das aber schon nicht mehr die einzige Großmacht des östlichen Mittelmeerraumes war.", "... herrschen wird. Das griechische Reich von Alexander dem Großen."] },
      { number: 40, text: "Das vierte Reich wird hart wie Eisen sein – Eisen zerschlägt und zermalmt ja alles – und wird wie Eisen alles zerschmettern, was sich ihm in den Weg stellt.*", footnotes: ["... in den Weg stellt. Das Römische Reich und seine Nachfolgestaaten."] },
      { number: 41, text: "Dass du aber die Füße und Zehen, teils aus Töpferton und teils aus Eisen bestehend, gesehen hast, bedeutet: Das Reich wird geteilt sein, aber es wird etwas von der Härte des Eisens in sich haben. Darum hast du das Eisen mit Ton vermischt gesehen." },
      { number: 42, text: "Und dass die Zehen teils von Eisen und teils von Ton sind, bedeutet: Das Reich wird zum Teil stark und zum Teil zerbrechlich sein." },
      { number: 43, text: "Das Nebeneinander von Eisen und Ton bedeutet: Sie werden versuchen, sich durch Heiraten miteinander zu verbinden, aber ihre Verbindung wird keinen Bestand haben, so wie sich Eisen eben nicht mit Ton verbinden lässt." },
      { number: 44, text: "In der Zeit dieser Königreiche wird der Gott des Himmels ein Reich errichten, das niemals untergehen wird. Dieses Reich wird nie einem anderen Volk überlassen werden, im Gegenteil: Es wird alle diese Königreiche zermalmen und zum Verschwinden bringen, selbst aber ewig bestehen." },
      { number: 45, text: "Das hast du in dem Stein gesehen, der ohne menschliches Zutun losbrach und Eisen, Bronze, Ton, Silber und Gold zermalmte. Ein großer Gott hat den König wissen lassen, was nach dieser Zeit geschehen wird. Der Traum sagt die Wahrheit und seine Deutung ist zuverlässig.\"" },
      { number: 46, text: "Da warf König Nebukadnezzar sich vor Daniel nieder, mit dem Gesicht auf dem Boden. Er befahl seinen Dienern, ihm Opfer und Weihrauch darzubringen," },
      { number: 47, text: "und sagte zu Daniel: \"Euer Gott ist wirklich ein Gott aller Götter, ein Herr der Könige und ein Offenbarer der Geheimnisse! Denn du hast dieses Geheimnis ja offenbaren können.\"" },
      { number: 48, text: "Dann machte der König Daniel groß: Er beschenkte ihn reich und ernannte ihn zum Statthalter der Provinz Babylon. Außerdem machte er ihn zum obersten Vorgesetzten für alle Weisen Babylons." },
      { number: 49, text: "Auf Daniels Bitte hin betraute der König Schadrach, Meschach und Abed-Nego mit der Verwaltung über die Provinz Babylon. Daniel selbst blieb am Hof des Königs." },
    ] },
    { number: 3, verses: [
      { number: 1, text: "König Nebukadnezzar ließ ein goldenes Standbild* anfertigen und in der Ebene von Dura* in der Provinz Babylon aufstellen. Es war 30 Meter hoch und 3 Meter breit.", heading: "Drei standhafte junge Männer", footnotes: ["Standbild. Aufgrund der Maße handelte es sich hier wohl eher um eine Art Obelisk, ein vergoldeter, mit Bildern versehener vierkantiger Steinpfeiler. Denkbar ist aber auch, dass das goldene Standbild auf einem sehr hohen Sockel stand.", "Ebene von Dura. Etwa 9 km südlich von Babel haben Archäologen einen großen quadratischen Block gefunden, der mitten in einem großen weiten Feld steht und die Grundlage für den Obelisk gewesen sein könnte."] },
      { number: 2, text: "Anschließend berief Nebukadnezzar die Satrapen, Präfekten und Statthalter seines Reiches ein, dazu die Ratgeber, Schatzmeister und Richter, die Befehlshaber der Polizei und alle anderen hohen Beamten. Sie sollten an der Einweihung des Standbildes teilnehmen, das er hatte aufstellen lassen." },
      { number: 3, text: "Sobald sie alle gekommen waren und sich vor dem Standbild aufgestellt hatten," },
      { number: 4, text: "rief ein Herold mit lauter Stimme: \"Folgender Befehl gilt allen hier versammelten Völkern, Nationen und Sprachen:" },
      { number: 5, text: "Sobald ihr den Klang der Hörner, Pfeifen und Zithern, der Leiern und Lauten, des Orchesters und aller anderen Instrumente hört, sollt ihr niederfallen und das goldene Standbild anbeten, das König Nebukadnezzar aufgestellt hat." },
      { number: 6, text: "Wer es nicht tut, wird auf der Stelle in den glühenden Ofen geworfen.\"" },
      { number: 7, text: "Als nun die Instrumente ertönten, die Hörner, Pfeifen und Zithern, die Leiern und Lauten und alle andere Musik, warfen sich die Menschen aus all den Völkern, Nationen und Sprachen vor dem goldenen Standbild nieder, das Nebukadnezzar aufgestellt hatte, und beteten es an." },
      { number: 8, text: "Bei dieser Gelegenheit traten einige chaldäische Männer heran" },
      { number: 9, text: "und sagten zu Nebukadnezzar: \"Der König lebe ewig!" },
      { number: 10, text: "Du, König, hast ein Edikt erlassen, dass jeder, der den Klang der Hörner, Pfeifen und Zithern, der Leiern und Lauten, des Orchesters und aller anderen Instrumente hört, niederfallen und das goldene Bild anbeten soll." },
      { number: 11, text: "Und wer es nicht tut, soll auf der Stelle in den glühenden Ofen geworfen werden." },
      { number: 12, text: "Nun gibt es hier einige jüdische Männer, denen du die Verwaltung der Provinz Babylon anvertraut hast: Schadrach, Meschach und Abed-Nego. Diese Männer schenken dir keine Beachtung, sie dienen deinen Göttern nicht und werfen sich auch nicht vor deinem goldenen Standbild nieder!\"" },
      { number: 13, text: "Da wurde Nebukadnezzar ärgerlich und befahl wütend, Schadrach, Meschach und Abed-Nego herzubringen. Als sie ihm vorgeführt wurden," },
      { number: 14, text: "fuhr er sie an: \"Ist es wahr, Schadrach, Meschach und Abed-Nego,* dass ihr meinen Göttern keine Ehre erweist und euch nicht vor meinem goldenen Standbild niederwerft?", footnotes: ["... Abed-Nego. Dass der König ihre Namen nennt, ist eine Geste der Achtung."] },
      { number: 15, text: "Ihr habt noch eine Gelegenheit! Wenn ihr jetzt noch einmal den Klang aller Instrumente hört und euch niederwerft und das Bild anbetet, das ich gemacht habe, dann ist die Sache erledigt. Wenn aber nicht, werdet ihr sofort in den glühenden Ofen geworfen. Welcher Gott soll euch dann noch aus meiner Hand retten?\"" },
      { number: 16, text: "Schadrach, Meschach und Abed-Nego erwiderten dem König Nebukadnezzar: \"Wir haben nicht die Absicht, uns vor dir zu verteidigen." },
      { number: 17, text: "Wenn unser Gott, dem wir dienen, uns retten will, dann wird er uns aus dem glühenden Ofen und aus deiner Gewalt retten." },
      { number: 18, text: "Und wenn nicht, so sollst du, König, dennoch wissen, dass wir deinen Göttern nicht dienen und dein goldenes Bild nicht anbeten werden.\"" },
      { number: 19, text: "Da geriet Nebukadnezzar noch mehr in Wut. Sein Gesicht verzerrte sich vor Zorn über Schadrach, Meschach und Abed-Nego. Er ließ den Ofen siebenmal so stark heizen wie sonst*.", footnotes: ["siebenmal so stark heizen wie sonst. Die Glut war von der Anzahl der Blasebälge abhängig, die gleichzeitig eingesetzt wurden."] },
      { number: 20, text: "Dann befahl er den stärksten Männern in seinem Heer, die drei zu fesseln und in den glühenden Ofen zu werfen." },
      { number: 21, text: "Sofort wurden sie in ihrer Kleidung, ihren Hosen, Mänteln und Mützen gefesselt und in den glühenden Ofen geworfen." },
      { number: 22, text: "Und weil der König befohlen hatte, ihn besonders stark zu heizen, wurden die Männer, die Schadrach, Meschach und Abed-Nego hinaufbrachten, von den herausschlagenden Flammen getötet." },
      { number: 23, text: "Die drei aber fielen gefesselt ins Feuer." },
      { number: 24, text: "Da erschrak der König Nebukadnezzar. Er fuhr auf und sagte zu seinen Ratgebern: \"Haben wir nicht drei Männer gefesselt ins Feuer geworfen?\" – \"Ja, gewiss, König!\", erwiderten sie." },
      { number: 25, text: "\"Warum sehe ich dann aber vier Männer ohne Fesseln im Feuer umhergehen? Sie sind alle unversehrt und der vierte sieht aus wie ein Göttersohn.\"" },
      { number: 26, text: "Nebukadnezzar trat näher an die Öffnung des Ofens und rief: \"Schadrach, Meschach, Abed-Nego, ihr Diener des höchsten Gottes, kommt heraus!\" Da kamen die drei aus dem Feuer." },
      { number: 27, text: "Die Satrapen und die Präfekten, die Statthalter und die Ratgeber des Königs kamen zusammen und sahen, dass das Feuer diesen Männern nichts hatte anhaben können: Ihr Haar war nicht versengt, ihre Kleidung war unversehrt, nicht einmal Brandgeruch konnte man an ihnen wahrnehmen." },
      { number: 28, text: "Da rief Nebukadnezzar aus: \"Gepriesen sei der Gott von Schadrach, Meschach und Abed-Nego! Er hat seinen Engel geschickt, um diese Männer zu retten, die sich auf ihn verließen und sich dem Befehl des Königs widersetzten. Sie haben ihr Leben gewagt, damit sie außer ihrem Gott keinen anderen verehren oder anbeten müssten!" },
      { number: 29, text: "Darum ergeht folgendes Edikt an alle Völker, Nationen und Sprachen: 'Jeder, der etwas Verächtliches über den Gott von Schadrach, Meschach und Abed-Nego sagt, dessen Haus wird zu einem Schutthaufen gemacht und er selbst wird in Stücke gehauen werden.' Denn es gibt keinen anderen Gott, der auf solch eine Weise retten kann!\"" },
      { number: 30, text: "Dann gab der König den drei Männern sehr hohe Ehrenstellungen in der Provinz Babylon." },
      { number: 31, text: "König Nebukadnezzar wendet sich an alle Völker, Nationen und Sprachen auf der ganzen Erde: Glück und Frieden euch allen!", heading: "Hochmut wird bestraft" },
      { number: 32, text: "Ich habe mich entschlossen, euch von den Zeichen und Wundern in Kenntnis zu setzen, die Gott, der Höchste, an mir getan hat." },
      { number: 33, text: "Wie groß sind seine Zeichen! Wie gewaltig seine Wunder! Sein Reich besteht ewig! Seine Herrschaft hat für immer Bestand!" },
    ] },
    { number: 4, verses: [
      { number: 1, text: "Ich, Nebukadnezzar, lebte ruhig und zufrieden in meinem Palast." },
      { number: 2, text: "Eines Nachts hatte ich einen Traum, der mich erschreckte. Ich lag auf meinem Bett und geriet durch das, was ich sah, in Angst." },
      { number: 3, text: "Deshalb ließ ich alle Weisen von Babylon zu mir kommen. Sie sollten meinen Traum deuten." },
      { number: 4, text: "Als die Magier, die Geisterbeschwörer, die Orakelpriester und die Astrologen vor mir standen, erzählte ich ihnen den Traum. Doch keiner sagte mir die Deutung." },
      { number: 5, text: "Zuletzt trat Daniel vor mich, den ich nach meinem Gott Beltschazzar genannt hatte. In ihm wohnt der Geist der heiligen Götter. Auch ihm erzählte ich meinen Traum." },
      { number: 6, text: "\"Beltschazzar\", sagte ich, \"du bist der Oberste der Magier. Ich weiß, dass der Geist der heiligen Götter in dir wohnt und dir kein Geheimnis zu schwer ist. Erkläre mir die Bilder, die ich in meinem Traum gesehen habe, und deute sie mir!" },
      { number: 7, text: "Folgende Schau hatte ich auf meinem Lager: Mitten auf der Erde sah ich einen sehr großen Baum." },
      { number: 8, text: "Er wurde immer größer und gewaltiger, so dass seine Spitze zuletzt bis an den Himmel reichte. Und bis ans Ende der Erde konnte man ihn sehen.*", footnotes: ["konnte man ihn sehen. In einer der Inschriften Nebukadnezzars wird Babylon mit einem Baum verglichen, der immer größer wird."] },
      { number: 9, text: "Er hatte schönes Laub und gab reichlich Frucht – Nahrung für alle. Den wilden Tieren bot er Schatten, die Vögel nisteten in seinen Zweigen. Alles, was lebte, bekam Nahrung von ihm." },
      { number: 10, text: "Als ich das Bild anschaute, kam auf einmal ein Wächterengel vom Himmel herab." },
      { number: 11, text: "Er rief laut: 'Fällt den Baum und hackt seine Äste ab! Reißt das Laub von seinen Ästen und verstreut die Früchte überall! Die Tiere unter ihm und die Vögel in seinen Zweigen sollen in die Flucht gejagt werden." },
      { number: 12, text: "Nur den Wurzelstock lasst in der Erde, doch fesselt ihn mit Bronze- und Eisenketten mitten zwischen Gras und Kräutern! Der Tau soll auf ihn fallen, und er soll im Gras liegen wie das Wild." },
      { number: 13, text: "Statt eines Menschenverstandes soll ihm der Verstand eines Tieres gegeben werden! Sieben Zeiten* lang soll das dauern.", footnotes: ["Zeiten. Perioden von unbestimmter Länge, vielleicht Jahre."] },
      { number: 14, text: "Dieses Edikt beruht auf einem Beschluss der Wächter im Himmel, es ist ein Befehl der heiligen Engel, damit alle Menschen erkennen: Der Höchste hat die Macht über die Reiche der Welt und kann sie geben, wem er will. Selbst den Niedrigsten der Menschen kann er zum Herrscher über alle machen.'" },
      { number: 15, text: "Diesen Traum habe ich, König Nebukadnezzar, gehabt. Aber du, Beltschazzar, deute ihn mir! Denn alle Weisen in meinem Reich können mir keine Deutung geben. Doch du kannst es, weil dich der Geist der heiligen Götter erfüllt.\"" },
      { number: 16, text: "Da erstarrte Daniel, der auch Beltschazzar heißt, eine Zeit lang. Seine Gedanken erschreckten ihn. Aber der König sagte: \"Beltschazzar, lass dir von dem Traum und seiner Deutung keine Angst einjagen!\" Er erwiderte: \"Mein Herr, ich wünschte, die Botschaft des Traums würde deinen Feinden gelten und allen, die dich hassen!" },
      { number: 17, text: "Der Baum, den du gesehen hast, der so groß und stark wurde, dass seine Spitze bis an den Himmel reichte, und den man bis ans Ende der Erde sehen konnte," },
      { number: 18, text: "der schönes Laub hatte, reichlich Frucht gab und alle mit Nahrung versorgte, der den wilden Tieren Schatten bot und in dessen Zweigen die Vögel nisteten –" },
      { number: 19, text: "dieser Baum bist du, König. Du wurdest groß und mächtig, deine Gewalt reichte bis an den Himmel, deine Herrschaft bis ans Ende der Welt." },
      { number: 20, text: "Dass der König einen der heiligen Wächterengel vom Himmel kommen sah, der befahl: 'Fällt den Baum und zerstört ihn! Doch seinen Wurzelstock lasst in der Erde, aber fesselt ihn mit Bronze- und Eisenketten mitten zwischen Gras und Kräutern! Der Tau soll auf ihn fallen, und er soll im Gras liegen wie das Wild, bis die sieben Zeiten vorbei sind!'," },
      { number: 21, text: "das, mein König, hat folgende Bedeutung: Der Höchste hat einen Beschluss gefasst, der meinen Herrn, den König, betrifft." },
      { number: 22, text: "Man wird dich aus der Gemeinschaft der Menschen ausstoßen und du wirst unter den wilden Tieren leben. Man wird dir Kraut zu essen geben wie den Rindern und dich nass werden lassen vom Tau.* Sieben Zeiten werden so vergehen, bis du erkennst, dass der Höchste über die Reiche der Menschen herrscht und die Herrschaft gibt, wem er will.", footnotes: ["... vom Tau. Nebukadnezzar sollte offenbar von einer Geisteskrankheit befallen werden, der Zwangsvorstellung, ein Tier zu sein. Auch die antiken Schriftsteller Euseb, Abydenus und Josephus zitieren einen Bericht des Griechen Megasthenes aus dem 3. Jh. v.Chr. über ein seltsames Benehmen Nebukadnezzars in seiner späteren Regierungszeit."] },
      { number: 23, text: "Doch weil der Wurzelstock im Erdreich bleiben sollte, wird auch dir dein Königreich erhalten bleiben, sobald du erkennst, dass der Himmel die Macht hat." },
      { number: 24, text: "Darum König, lass dir meinen Rat gefallen und sühne deine Sünden durch Gerechtigkeit, dein Unrecht durch Erbarmen mit den Armen. Dann wird es dir auch in Zukunft gut gehen!\"" },
      { number: 25, text: "Genauso geschah es dann mit König Nebukadnezzar." },
      { number: 26, text: "Zwölf Monate später ging er auf der Dachterrasse seines Palastes in Babylon umher" },
      { number: 27, text: "und sagte sich: \"Diese großartige Stadt hier habe ich gebaut! Es ist meine Residenz! Mit meiner gewaltigen Macht habe ich das fertig gebracht, ein würdiges Denkmal meiner Herrlichkeit!\"*", footnotes: ["meiner Herrlichkeit. Nach der Zerstörung durch den Assyrerkönig Sanherib hatte Nebukadnezzar die Stadt wieder aufgebaut und zu einer der glänzendsten und prächtigsten Städte des Altertums gemacht. Die Stadt war von dreifachen Gräben und Wällen umgeben und hatte bis zu sieben Meter dicke Mauern aus Lehmziegeln mit einer Gesamtlänge von 89 km. Die hängenden Gärten, terassenförmige Gartenanlagen auf dem Gelände des Königspalastes, mit ihrem hoch entwickelten Bewässerungssystem gehörten zu den sieben Weltwundern der Antike."] },
      { number: 28, text: "Der König hatte noch nicht ausgeredet, da ertönte eine Stimme aus dem Himmel: \"Hiermit wird dir die Herrschaft weggenommen, König Nebukadnezzar!" },
      { number: 29, text: "Du wirst aus der Gemeinschaft der Menschen ausgestoßen und musst unter den wilden Tieren leben!* Man wird dir Kraut zu essen geben wie dem Rind und dich nass werden lassen vom Tau. Sieben Zeiten werden so vergehen, bis du erkennst, dass der Höchste über die Reiche der Menschen herrscht und die Herrschaft gibt, wem er will.\"", footnotes: ["unter den wilden Tieren leben. Vermutlich im Palastgarten."] },
      { number: 30, text: "Im gleichen Augenblick wurde das Urteil an Nebukadnezzar vollstreckt. Er wurde aus der Gemeinschaft der Menschen ausgestoßen, aß Kraut wie das Rind und wurde nass vom Tau. Sein Haare wurden wie Adlerfedern und seine Nägel so lang wie die Krallen der Vögel." },
      { number: 31, text: "Nach Ablauf der Zeit erhob ich, Nebukadnezzar, den Blick zum Himmel. Da kehrte mein Verstand wieder zurück und ich pries den Höchsten. Ich rühmte und verherrlichte den, der ewig lebt, dessen Herrschaft niemals aufhört und dessen Reich in Ewigkeit besteht." },
      { number: 32, text: "Alle Bewohner der Erde sind vor ihm wie nichts. Er macht mit ihnen, was er will. Selbst das Heer des Himmels* ist in seiner Hand. Niemand kann ihm wehren und ihn fragen, was er da tut.", footnotes: ["Heer des Himmels. Das meint die Bewohner der überirdischen Welt, die Engelmächte, im Gegensatz zu den Bewohnern dieser Welt."] },
      { number: 33, text: "Als mein Verstand wieder zurückgekehrt war, kehrten zum Ruhm meines Königtums auch meine Herrlichkeit und meine Gesundheit zurück. Meine Ratgeber und die Großen meines Reiches suchten mich auf, und ich wurde wieder in meine Herrschaft eingesetzt. Meine Macht wurde noch größer als vorher." },
      { number: 34, text: "Nun rühme und preise ich, Nebukadnezzar, den König des Himmels. Ich ehre ihn, denn er steht zu seinem Wort, und alles, was er tut, ist recht. Alle, die sich überheben, kann er demütigen." },
    ] },
    { number: 5, verses: [
      { number: 1, text: "König Belschazzar* veranstaltete ein großes Bankett für die tausend Mächtigen seines Reiches und trank mit ihnen Wein.", heading: "Die Schrift an der Wand", footnotes: ["Um 550 v.Chr. hatte Nabonid seinem Sohn Belschazzar die Herrschaft über das babylonische Reich gegeben und war selbst nach Tema gezogen, um ganz Arabien zu unterwerfen. Inzwischen hatte sich der persische König Kyrus erhoben. 539 marschierte er in Babylonien ein, nachdem er den zurückgekehrten Nabonid in zwei Schlachten besiegt hatte. Am 12. Oktober 539 drangen die Perser in Babylon ein. Belschazzar hatte sich in dem riesigen Königspalast verschanzt. Die in Kapitel 5 geschilderte Szene beschreibt den letzten Tag seines Lebens."] },
      { number: 2, text: "Unter dem Einfluss des Weins befahl er, die goldenen und silbernen Gefäße herzubringen, die sein Vater Nebukadnezzar* aus dem Tempel in Jerusalem hatte wegnehmen lassen. Er wollte mit seinen Mächtigen, seinen Frauen und Nebenfrauen daraus trinken.", footnotes: ["Vater Nebukadnezzar. Belschazzars Mutter war eine Tochter Nebukadnezzars."] },
      { number: 3, text: "Da brachte man die goldenen Gefäße, die einst aus dem Tempel Gottes in Jerusalem weggenommen worden waren, und alle tranken Wein daraus." },
      { number: 4, text: "Dabei rühmten sie die Götter aus Gold und Silber, aus Bronze, Eisen, Holz und Stein." },
      { number: 5, text: "Im gleichen Augenblick erschienen die Finger einer menschlichen Hand und schrieben etwas auf die weiß verputzte Wand des Königspalastes. Es war die Stelle gegenüber dem Leuchter. Als der König die schreibende Hand sah," },
      { number: 6, text: "wurde er bleich. Seine Gedanken erschreckten ihn so sehr, dass er am ganzen Körper schlotterte und seine Knie aneinander schlugen." },
      { number: 7, text: "Laut schrie er nach den Beschwörungspriestern, den Astrologen und Magiern. Als die Weisen Babylons eintraten, sagte er zu ihnen: \"Wer diese Schrift lesen und mir deuten kann, soll in Purpur gekleidet werden und bekommt eine goldene Ehrenkette um den Hals. Er soll der dritte Mann* im ganzen Reich werden.\"", footnotes: ["dritter Mann. Weil Belschazzar selbst nur der Zweite war."] },
      { number: 8, text: "Nun traten die Weisen des Königs heran, aber sie konnten die Schrift weder lesen noch deuten." },
      { number: 9, text: "Darüber erschrak König Belschazzar noch mehr; er wurde immer bleicher, und auch seine Mächtigen gerieten in Angst." },
      { number: 10, text: "Weil nun die Rufe des Königs und seiner Mächtigen bis zur Königsmutter drangen, kam sie in den Festsaal und sagte: \"Der König lebe ewig! Lass dich von deinen Gedanken nicht schrecken, du musst nicht blass werden." },
      { number: 11, text: "Es gibt einen Mann in deinem Reich, der vom Geist der heiligen Götter erfüllt ist. Zur Zeit deines Vaters Nebukadnezzar* bewies er, dass Erleuchtung und Einsicht in ihm wohnten, eine Weisheit, wie sie sonst nur die Götter haben. Dein Vater hatte ihn zum Obersten aller Zeichendeuter, Beschwörungspriester, Astrologen und Magier gemacht, dein Vater, König!", footnotes: ["Nebukadnezzar war 23 Jahre vorher, im Jahr 562 v.Chr., gestorben."] },
      { number: 12, text: "Er heißt Daniel, und dein Vater hatte ihm den Namen Beltschazzar gegeben. Der Mann ist außergewöhnlich klug, er hat Verstand und Scharfsinn zum Deuten von Träumen und kann auch sonst jedes Rätsel lösen und die geheimnisvollsten Dinge erklären. Lass ihn jetzt rufen! Er wird dir sagen, was die Schrift bedeutet.\"" },
      { number: 13, text: "Darauf wurde Daniel herbeigeholt, und der König sagte: \"Du bist also Daniel*, einer von den Juden, die mein königlicher Vater aus Juda hergebracht hat?", footnotes: ["Daniel. Belschazzar hatte offenbar keine Ahnung von Daniel, der inzwischen mindestens 80 Jahre alt war und nicht mehr im königlichen Dienst stand."] },
      { number: 14, text: "Ich habe gehört, dass du vom Geist der Götter erfüllt und mit außergewöhnlicher Weisheit, mit Erleuchtung und Einsicht begabt bist." },
      { number: 15, text: "Gerade sind die Weisen, die Beschwörungspriester vor mich gebracht worden, um diese Schrift hier zu lesen und ihren Sinn zu deuten. Aber sie können es nicht." },
      { number: 16, text: "Aber du – von dir habe ich gehört, dass du Deutungen geben und schwierige Rätsel lösen kannst. Wenn das stimmt und du mir die Schrift vorlesen und erklären kannst, wirst du in Purpur gekleidet werden, bekommst eine goldene Ehrenkette um den Hals und sollst als dritter Mann im Reich herrschen.\"" },
      { number: 17, text: "Daniel erwiderte dem König: \"Behalte deine Geschenke oder gib sie einem anderen. Aber die Schrift werde ich dem König vorlesen und sagen, was sie bedeutet." },
      { number: 18, text: "Du, König, – Gott, der Höchste, hatte deinen Vater Nebukadnezzar zu einem mächtigen Herrscher gemacht und ihm Ehre und Ruhm gegeben." },
      { number: 19, text: "Wegen dieser ihm verliehenen Macht zitterten ganze Völker, Nationen und Sprachen vor ihm. Er tötete oder ließ am Leben, wen er wollte. Er erhöhte die einen und erniedrigte die anderen – wie es ihm gefiel." },
      { number: 20, text: "Doch als er überheblich wurde und sein Geist sich maßlos überhob, verlor er Thron und Herrscherwürde." },
      { number: 21, text: "Er wurde aus der Gemeinschaft der Menschen ausgestoßen und bekam statt eines Menschenverstandes den eines Tieres. Er musste bei den Wildeseln leben und Gras fressen wie ein Rind. Sein Körper wurde vom Tau des Himmels nass, bis er erkannte, dass Gott, der Höchste, über die Reiche der Menschen herrscht und die Herrschaft gibt, wem er will." },
      { number: 22, text: "Aber du, Belschazzar, sein Sohn, hast dich nicht gedemütigt, obwohl du das alles wusstest." },
      { number: 23, text: "Du hast dich gegen den Herrn des Himmels erhoben und dir die Gefäße aus seinem Tempel herbeischaffen lassen. Und mit deinen Mächtigen, mit deinen Frauen und Nebenfrauen hast du Wein daraus getrunken. Und dabei hast du die Götter aus Gold und Silber, aus Bronze, Eisen, Holz und Stein gepriesen, die weder sehen noch hören können und keinen Verstand haben. Aber den Gott, der dein Leben in der Hand hat und der dein Schicksal bestimmt, ihn hast du nicht geehrt." },
      { number: 24, text: "Darum hat er diese Hand geschickt und diese Worte an die Wand schreiben lassen." },
      { number: 25, text: "Sie lauten: 'Mene, mene, tekel uparsin'" },
      { number: 26, text: "und haben folgende Bedeutung: Mene – gezählt hat Gott die Tage deiner Herrschaft und ihr ein Ende gesetzt." },
      { number: 27, text: "Tekel – gewogen hat er dich auf seiner Waage und dich zu leicht gefunden." },
      { number: 28, text: "Peres – zerteilt hat er dein Reich und es den Medern und Persern gegeben.\"" },
      { number: 29, text: "Da befahl Belschazzar, Daniel in Purpur zu kleiden und ihm eine goldene Halskette umzulegen. Dann ließ er verkünden, dass er als der Dritte in seinem Reich herrschen sollte." },
      { number: 30, text: "Noch in derselben Nacht wurde König Belschazzar, der ein Chaldäer war, getötet;" },
      { number: 6, text: "und Darius*, ein Meder, übernahm im Alter von 62 Jahren die Herrschaft.", footnotes: ["Darius, der Meder, ist wahrscheinlich identisch mit dem Statthalter Gubaru, der am 29. Oktober 539 v.Chr. von Kyrus eingesetzt wurde und 14 Jahre lang über Mesopotamien, Syrien, Phönizien und das Gebiet Israels mit umfassender Machtfülle regierte."] },
    ] },
    { number: 6, verses: [
      { number: 2, text: "Darius beschloss, 120 Satrapen über die Provinzen seines Reiches einzusetzen.", heading: "Daniel in der Löwengrube" },
      { number: 3, text: "Diese Statthalter unterstellte er drei Ministern, von denen einer Daniel war. Sie hatten ihnen Rechenschaft abzulegen, damit der König nicht belästigt würde." },
      { number: 4, text: "Bald stellte sich heraus, dass Daniel den anderen Ministern und den Satrapen weit überlegen war, weil ein außergewöhnlicher Geist in ihm wohnte. Der König dachte sogar daran, ihm die Verwaltung des ganzen Reiches zu übertragen." },
      { number: 5, text: "Da versuchten die anderen Minister zusammen mit den Satrapen, Daniel wegen seiner Amtsführung anzuklagen. Aber sie konnten keinen Grund zur Anklage und keine Korruption entdecken, denn er war weder nachlässig noch bestechlich." },
      { number: 6, text: "Da sagten sie sich: \"Wir haben bei diesem Daniel nichts in der Hand, es sei denn, wir finden im Gesetz seines Gottes etwas gegen ihn.\"" },
      { number: 7, text: "Darauf eilten sie aufgeregt zum König und sagten: \"Der König Darius lebe ewig!" },
      { number: 8, text: "Alle Minister des Reiches, die Statthalter, die Satrapen, die Ratgeber und Verwalter sind übereingekommen, dich zu bitten, folgende Verordnung zu erlassen: 'Wer in den kommenden dreißig Tagen eine Bitte an irgendeinen Gott oder Menschen richtet außer an dich, König, soll zu den Löwen in die Grube geworfen werden.'" },
      { number: 9, text: "Gib dem Gebot die Form eines offiziellen königlichen Erlasses, der nach dem Gesetz der Meder und Perser nicht geändert oder aufgehoben werden darf!\"" },
      { number: 10, text: "König Darius ließ den Erlass ausfertigen und unterschrieb ihn." },
      { number: 11, text: "Als Daniel erfuhr, dass der Erlass abgefasst worden war, ging er in sein Haus. Im Obergeschoss hatte er offene Fenster in Richtung Jerusalem. Dreimal täglich kniete er dort nieder, um seinen Gott zu preisen und seine Bitten vor ihn zu bringen. So tat er es auch jetzt." },
      { number: 12, text: "Da stürmten jene Männer herein und fanden Daniel, wie er zu seinem Gott betete und ihn sogar anflehte." },
      { number: 13, text: "Darauf gingen sie zum König und brachten das königliche Verbot zur Sprache: \"Hast du nicht einen Erlass unterschrieben, dass jeder, der in den nächsten dreißig Tagen von irgendeinem Gott oder Menschen etwas erbittet außer von dir, König, zu den Löwen in die Grube geworfen werden soll?\" – \"So ist es\", erwiderte der König. \"Es gilt unwiderruflich nach dem Gesetz der Meder und Perser, das nicht aufgehoben werden darf.\"" },
      { number: 14, text: "Da sagten sie dem König: \"Daniel, einer von den hergebrachten Juden, kümmert sich einfach nicht um dich und dein Gebot, sondern verrichtet dreimal am Tag sein Gebet.\"" },
      { number: 15, text: "Als der König das hörte, wurde er sehr traurig. Den ganzen Tag über unternahm er alle Anstrengungen, Daniel zu retten." },
      { number: 16, text: "Bei Sonnenuntergang kamen die Kläger wieder zu ihm und hielten ihm vor: \"Du weißt, König, dass nach dem Gesetz der Meder und Perser kein Erlass des Königs widerrufen werden kann!\"" },
      { number: 17, text: "Nun musste der König den Befehl geben, Daniel herzubringen und in die Grube zu den Löwen zu werfen. Er sagte zu ihm: \"Dein Gott, dem du so treu dienst, möge er dich retten!\"" },
      { number: 18, text: "Dann wurde ein Stein auf die Öffnung der Grube gewälzt und mit dem Siegel des Königs und seiner Mächtigen versiegelt, damit in Daniels Sache nichts verändert würde." },
      { number: 19, text: "Danach zog sich Darius in seinen Palast zurück. Er verzichtete auf jede Unterhaltung*, fastete die ganze Nacht und konnte auch keinen Schlaf finden.", footnotes: ["Unterhaltung. Andere übersetzen das unbekannte aramäische Wort mit Nebenfrauen, Speisen oder Musikinstrumenten."] },
      { number: 20, text: "In der Morgendämmerung, gerade als es hell wurde, stand er auf und ging voller Unruhe zur Löwengrube." },
      { number: 21, text: "Als er in die Nähe der Grube gekommen war, rief er mit schmerzerfüllter Stimme: \"Daniel, du Diener des lebendigen Gottes! Dein Gott, dem du so treu dienst – hat er dich vor den Löwen retten können?\"" },
      { number: 22, text: "Daniel antwortete: \"Der König lebe ewig!" },
      { number: 23, text: "Mein Gott hat seinen Engel geschickt, weil ihm meine Unschuld bekannt war. Und der hat den Löwen die Rachen verschlossen, sodass sie mir nichts antun konnten. Auch dir gegenüber, König, habe ich kein Unrecht begangen.\"" },
      { number: 24, text: "Da freute sich der König außerordentlich und befahl, Daniel aus der Grube herauszuholen. Als man ihn heraufgezogen hatte, fand man keinerlei Verletzung an ihm, weil er seinem Gott vertraut hatte." },
      { number: 25, text: "Dann befahl der König, die Männer, die Daniel verleumdet hatten, samt ihren Frauen und Kindern herzuholen und in die Grube zu den Löwen zu werfen. Und noch ehe sie den Boden der Grube berührt hatten, fielen die Löwen über sie her und zermalmten ihnen alle Knochen." },
      { number: 26, text: "Daraufhin schickte König Darius ein Schreiben an alle Völker, Nationen und Sprachen. Es lautete folgendermaßen: \"Glück und Frieden euch allen!" },
      { number: 27, text: "Hiermit ordne ich an, dass man in meinem ganzen Reich den Gott Daniels scheuen und fürchten soll. Denn er ist der lebendige, ewige Gott. Sein Reich geht nie zugrunde, und seine Herrschaft bleibt für immer bestehen." },
      { number: 28, text: "Er rettet und befreit; er wirkt Zeichen und Wunder am Himmel und auf der Erde; er hat Daniel aus den Klauen der Löwen gerettet.\"" },
      { number: 29, text: "Dieser Daniel war ein einflussreicher Mann unter der Regierung des Darius und auch unter der des Persers Kyrus." },
    ] },
    { number: 7, verses: [
      { number: 1, text: "Im ersten Regierungsjahr* des Königs Belschazzar von Babylon hatte Daniel im Traum eine Vision. Als er auf dem Bett lag, gingen Bilder durch seinen Kopf. Er schrieb auf, was er gesehen hatte.", heading: "7-12: Die Danielgesichte – Wie Gottes Herrschaft zum Ziel kommen wird\nDie Schau vom ewigen Reich", footnotes: ["Regierungsjahr. Nach babylonischer Zählweise ist damit das erste volle Regierungsjahr gemeint. Für Belschazzar war es das erste Jahr nach Abreise seines Vaters, der zur Eroberung Arabiens nach Tema aufgebrochen war, 548 v.Chr."] },
      { number: 2, text: "Hier ist sein Bericht: Ich sah in meiner nächtlichen Vision, wie aus allen vier Himmelsrichtungen Stürme kamen, die das große Meer aufwühlten." },
      { number: 3, text: "Vier große Tiere stiegen aus dem Meer; jedes hatte eine andere Gestalt." },
      { number: 4, text: "Das erste sah aus wie ein Löwe, hatte aber Flügel wie Adler. Während ich es betrachtete, wurden ihm die Flügel ausgerissen; es wurde aufgerichtet und wie ein Mensch auf zwei Füße gestellt. Es bekam auch das Herz eines Menschen." },
      { number: 5, text: "Das zweite Tier sah aus wie ein Bär. Es hatte sich auf einer Seite aufgerichtet und hielt drei Rippen zwischen seinen Zähnen. Man rief ihm zu: \"Steh auf und friss dich voll mit Fleisch!\"" },
      { number: 6, text: "Danach sah ich ein Tier, das wie ein Leopard aussah. Doch es hatte vier Flügel an seinen Seiten und auch vier Köpfe. Ihm wurde eine große Macht anvertraut." },
      { number: 7, text: "Danach erblickte ich in meiner Vision ein viertes Tier, das grauenerregend anzusehen war. Es war außergewöhnlich stark und hatte große eiserne Zähne. Es fraß und zermalmte und zertrat den Rest mit den Füßen. Es unterschied sich völlig von den anderen Tieren und hatte auch zehn Hörner." },
      { number: 8, text: "Als ich die Hörner beobachtete, wuchs auf einmal ein kleines Horn zwischen ihnen hoch. Seinetwegen wurden drei andere Hörner herausgerissen. Dann sah ich auf einmal Menschenaugen an diesem Horn und ein Maul, das große Reden schwang." },
      { number: 9, text: "Ich sah immer noch hin, bis Throne aufgestellt wurden und einer, der uralt war, sich setzte. Sein Gewand war weiß wie Schnee und sein Haar so hell wie reine Wolle. Sein Thron bestand aus Flammen und feurigen Rädern." },
      { number: 10, text: "Ein ganzer Feuerstrom flutete aus ihm. Tausende und Abertausende standen zu seinem Dienst bereit, und eine unzählbare Menge hatte sich vor ihm versammelt. Das Gericht setzte sich, und Bücher wurden aufgeschlagen." },
      { number: 11, text: "Ich schaute wieder auf das Horn, das so prahlerisch dahergeredet hatte, und sah, wie das ganze Tier getötet und sein Körper in die lodernde Glut geworfen und vernichtet wurde." },
      { number: 12, text: "Den übrigen Tieren wurde die Herrschaft genommen, doch ließ man jedes bis zu einer bestimmten Frist am Leben." },
      { number: 13, text: "Immer noch sah ich die nächtlichen Bilder: Da kam mit den Wolken des Himmels einer, der aussah wie der Sohn eines Menschen*. Man führte ihn zu dem, der uralt war,", footnotes: ["Sohn eines Menschen oder Menschensohn. Eine Bezeichnung, die Jesus später häufig auf sich angewandt hat, z.B. Lukas 5,24. Auch den ganzen Vers wendet er auf sich an: Matthäus 24,30; Markus 13,26; Lukas 21,27."] },
      { number: 14, text: "und verlieh ihm Macht und Ehre und übergab ihm die Herrschaft. Die Menschen aller Völker, Nationen und Sprachen dienten ihm. Seine Herrschaft ist ewig, sie wird nicht vergehen, sein Reich wird niemals zerstört." },
      { number: 15, text: "Ich, Daniel, litt unter dem, was ich sah, und die Bilder, die mir durch den Kopf gingen, erschreckten mich." },
      { number: 16, text: "Ich wandte mich an einen der Umstehenden und bat ihn, mir genau zu erklären, was das alles bedeute. Er sagte:" },
      { number: 17, text: "\"Diese großen Tiere, vier an der Zahl, versinnbildlichen vier Herrscher, die nacheinander auftreten werden." },
      { number: 18, text: "Doch empfangen werden das Reich die Heiligen des Höchsten*, und sie werden es für immer und in alle Ewigkeit besitzen.\"", footnotes: ["Heilige des Höchsten. Gottes heiliges Volk."] },
      { number: 19, text: "Dann wollte ich Genaueres über das vierte Tier wissen, das sich so sehr von allen anderen unterschied – diese schreckliche Bestie mit Zähnen aus Eisen und Krallen aus Bronze –, das fraß und zermalmte und den Rest mit den Füßen zertrat." },
      { number: 20, text: "Auch über die zehn Hörner auf seinem Kopf wollte ich mehr erfahren und besonders über das, das zuletzt hervorbrach und drei andere verdrängt hatte, das Augen hatte und einen Mund, der großmäulige Reden schwang, und das größer aussah als die übrigen Hörner." },
      { number: 21, text: "Ich hatte gesehen, wie dieses Horn gegen die Heiligen Krieg führte und sie besiegte." },
      { number: 22, text: "Aber dann hatte der eingegriffen, der uralt war, und den Heiligen des Höchsten das Gericht übertragen. Die Zeit war gekommen, dass die Heiligen das Reich in Besitz nahmen." },
      { number: 23, text: "Auf meine Frage antwortete er: \"Das vierte Tier bedeutet: Ein viertes Reich* wird auf der Erde entstehen, das sich von allen früheren unterscheidet. Es wird die Völker der Erde fressen, sie zertreten und zermalmen.", footnotes: ["viertes Reich. Vermutlich das Römische Reich, das gleichzeitig eine Art Modell für das antichristliche Reich der Endzeit sein wird, das wiederum aus den Nachfolgestaaten des Römischen Reiches herauswachsen wird."] },
      { number: 24, text: "Die zehn Hörner bedeuten, dass zehn Könige in diesem Reich regieren werden. Aber dann kommt ein König an die Macht, der ganz anders ist als seine Vorgänger. Er wird drei Könige stürzen" },
      { number: 25, text: "und es sich erlauben, Worte gegen den Höchsten zu richten. Er wird die Heiligen des Höchsten aufreiben und versuchen, Zeiten und Gesetz zu ändern. Die Heiligen werden für eine Zeit, zwei Zeiten und eine halbe Zeit* in seiner Gewalt sein.", footnotes: ["Zeit Zeit meint hier vielleicht Jahr. Es geht dann um eine Zeit von dreieinhalb Jahren wie auch in Offenbarung 12,14, was dort durch die 1260 Tage im gleichen Kapitel (Vers 6) bestätigt wird."] },
      { number: 26, text: "Dann aber tritt das Gericht zusammen. Es nimmt ihm seine Macht und zerstört sie bis zum letzten Rest." },
      { number: 27, text: "Das Reich und die Herrschaft und die Macht und Größe aller anderen Reiche zusammen werden dann dem Volk der Heiligen des Höchsten gegeben. Sein Reich ist ein ewiges Reich und alle Mächte werden ihm dienen und gehorchen.\"" },
      { number: 28, text: "Hier endet mein Bericht.* Mich, Daniel, schreckten meine Gedanken sehr, und alle Farbe wich aus meinem Gesicht. Doch ich behielt die Sache in meinem Herzen.", footnotes: ["Kapitel 8,1 – 12,13 sind wieder in Hebräisch verfasst."] },
    ] },
    { number: 8, verses: [
      { number: 1, text: "Im dritten Regierungsjahr* des Königs Belschazzar hatte ich, Daniel, eine zweite Vision.", heading: "Daniels zweite Vision", footnotes: ["dritten Regierungsjahr. Wahrscheinlich 547/46 v.Chr."] },
      { number: 2, text: "Dabei sah ich mich selbst, wie ich am Ulai-Kanal in der Residenz Susa stand, die sich in der Provinz Elam befindet." },
      { number: 3, text: "Ich blickte auf, da stand auf einmal ein Schafbock mit zwei mächtigen Hörnern am Kanal. Das eine Horn war größer als das andere, obwohl es erst später gewachsen war." },
      { number: 4, text: "Ich sah, wie der Schafbock nach Westen, Norden und Süden stieß. Kein Tier konnte ihm standhalten, und es gab keinen, der sich aus seiner Gewalt retten konnte. Er tat, was er wollte, und machte sich groß." },
      { number: 5, text: "Als ich aufmerksam hinsah, kam plötzlich ein Ziegenbock vom Westen her. Er flog nur so über die Erde, ohne den Boden zu berühren. Zwischen seinen Augen hatte er ein auffälliges Horn." },
      { number: 6, text: "Als er bei dem Schafbock angelangt war, den ich am Kanal gesehen hatte, stürzte er sich mit voller Wucht auf ihn." },
      { number: 7, text: "Ich sah ihn auf die Seite des Schafbocks aufprallen. Voller Erbitterung stieß er den Schafbock und brach ihm beide Hörner ab. Der hatte nicht die Kraft, ihm standzuhalten; er wurde zu Boden geworfen und zertrampelt. Niemand kam ihm zu Hilfe." },
      { number: 8, text: "Der Ziegenbock wurde immer größer. Auf dem Höhepunkt seiner Macht brach sein großes Horn ab. An seiner Stelle wuchsen vier kräftige Hörner in die vier Himmelsrichtungen hin." },
      { number: 9, text: "Aus einem von ihnen kam ein weiteres Horn hervor. Zuerst war es ganz klein, aber dann wuchs es gewaltig nach Süden, Osten und dem Land der Zierde, nach Israel, hin." },
      { number: 10, text: "Ja, es wuchs bis zum Heer des Himmels hin und schleuderte einige von diesem Heer und von den Sternen auf die Erde und zertrampelte sie." },
      { number: 11, text: "Selbst bis zum Befehlshaber des Himmelsheeres reckte es sich empor. Es nahm ihm das tägliche Opfer weg und verwüstete sein Heiligtum." },
      { number: 12, text: "Verbrecherisch setzte es ein ganzes Heer gegen das tägliche Opfer ein. So trat es die Wahrheit mit Füßen. Und bei allem, was es unternahm, hatte es Erfolg." },
      { number: 13, text: "Dann hörte ich, wie einer der heiligen Engel einen anderen fragte: \"Wie lange soll nach der Vision das tägliche Opfer unterbunden und das Heiligtum durch frevelhafte Entweihung verödet sein?\"" },
      { number: 14, text: "Dieser antwortete mir: \"Wenn 2300 Abend- und Morgenopfer vergangen sind*, wird die Ordnung des Heiligtums wiederhergestellt sein.\"", footnotes: ["vergangen sind. Das sind 1150 Tage, die gut in den Zeitraum zwischen der Entweihung des Tempels durch Antiochus Epiphanes IV. am 6. Dezember 167 v.Chr. und seiner Wiedereinweihung am 4. Dezember 164 v.Chr. passen. Streng genommen laufen die Tage erst am 31. Januar 163 v.Chr. aus, was aber genau der Voraussage entspricht."] },
      { number: 15, text: "Als ich, Daniel, die Vision hatte und sie zu verstehen suchte, stand plötzlich einer vor mir, der wie ein Mann aussah." },
      { number: 16, text: "Gleichzeitig hörte ich eine Stimme über dem Ulai-Kanal, die ihm zurief: \"Gabriel, erkläre ihm die Vision!\"" },
      { number: 17, text: "Da kam er auf mich zu. Als er näher trat, erschrak ich so sehr, dass ich zu Boden stürzte. Doch er sagte zu mir: \"Du, Mensch, sollst verstehen, dass diese Vision sich auf die letzte Zeit bezieht.\"" },
      { number: 18, text: "Während er das sagte, lag ich wie betäubt auf der Erde mit dem Gesicht zum Boden. Da berührte er mich und stellte mich wieder auf die Beine." },
      { number: 19, text: "Dann sagte er: \"Ich will dir erklären, was am Ende des Strafgerichts geschehen wird. Denn es geht um die Zeit, in der das Ende kommt." },
      { number: 20, text: "Der Schafbock mit den beiden Hörnern meint die Könige von Medien und Persien," },
      { number: 21, text: "der zottige Ziegenbock das griechische Königreich. Das große Horn zwischen den Augen des Ziegenbocks ist der erste König des Griechenreiches.*", footnotes: ["Griechenreiches. Alexander der Große war von 336-323 v.Chr. König von Griechenland. Er starb im Alter von 32 Jahren in Babylon."] },
      { number: 22, text: "Dass es abbrach und dass an seiner Stelle vier andere aufwuchsen, bedeutet: Aus dem Griechenvolk werden vier Reiche entstehen*, die aber nicht so viel Macht haben wie der erste König.", footnotes: ["vier Reiche. Das waren die so genannten Diadochenreiche, ehemalige Generäle und Freunde Alexanders, die nach seinem Tod das Reich aufteilten und sich in wechselnden Bündnissen gegenseitig bekämpften."] },
      { number: 23, text: "Wenn dann die Herrschaft dieser Reiche zu Ende geht und das Maß ihrer Untaten voll ist, wird ein frecher und hinterlistiger König* auftreten.", footnotes: ["frecher ... König. Antiochus Epiphanes IV. (175-164 v.Chr.)."] },
      { number: 24, text: "Er wird sehr mächtig werden, wenn auch nicht durch eigene Kraft, und wird ungeheures Verderben anrichten. Was er unternimmt, wird ihm gelingen. Er wird die Starken vernichten und Gottes heiliges Volk ins Verderben stürzen." },
      { number: 25, text: "Dank seiner Schlauheit gelingt ihm der Betrug. In seinem Größenwahn wird er viele ahnungslose Menschen umbringen. Selbst gegen den höchsten Herrn wird er sich erheben, aber schließlich ohne menschliches Zutun* zerschmettert werden.", footnotes: ["ohne menschliches Zutun. Er starb 164 v.Chr. bei einem Vorstoß nach Persien durch Krankheit oder Unfall."] },
      { number: 26, text: "Auch was du über die Abend- und Morgenopfer gehört hast, ist wahr. Doch du sollst das, was du gesehen hast, gut verwahren, denn es bezieht sich auf viele Tage.\"" },
      { number: 27, text: "Danach war ich, Daniel, völlig erschöpft und tagelang krank. Als ich wieder aufstehen konnte, nahm ich meinen Dienst beim König wieder auf. Doch ich war fassungslos über das Geschaute, und es gab niemand, der es verstand." },
    ] },
    { number: 9, verses: [
      { number: 1, text: "Im ersten Jahr, nachdem der Meder Darius*, der Sohn des Ahasveros*, über das Reich der Chaldäer zum König eingesetzt worden war,", heading: "Daniels Gebet und Botschaft", footnotes: ["der Meder Darius. Nicht zu verwechseln mit dem späteren Perserkönig Darius I., siehe auch die Fußnote zu Daniel 6,1.", "Ahasveros. Nicht zu verwechseln mit dem Ahasveros oder Xerxes im Buch Ester."] },
      { number: 2, text: "in seinem ersten Regierungsjahr* forschte ich, Daniel, in den Schriftrollen nach der Zahl der Jahre, die Jerusalem nach dem Wort Jahwes an den Propheten Jeremia in Trümmern liegen sollte; es waren siebzig*.", footnotes: ["ersten Regierungsjahr. Das erste volle Jahr seiner Herrschaft war 538/7 v.Chr.", "siebzig. Jeremia 25,11-12. Der Prophet weissagte das im Jahr 605 v.Chr. Vergleiche auch 29,10."] },
      { number: 3, text: "Ich wandte mein Gesicht zu Gott, dem Herrn, um zu ihm zu beten und ihn anzuflehen. Dabei fastete ich, hatte den Trauersack angezogen und saß in der Asche." },
      { number: 4, text: "Ich betete zu Jahwe, meinem Gott, und bekannte:\"Ach, Herr, du großer und furchterregender Gott! In unerschütterlicher Treue stehst du zu deinem Bund mit denen, die dich lieben und deine Gebote halten." },
      { number: 5, text: "Doch wir haben gesündigt, wir haben uns an dir vergangen und gottlos gehandelt, wir haben uns aufgelehnt und sind abgewichen von deinem Gebot und Gesetz." },
      { number: 6, text: "Wir haben auch nicht auf die Warnungen deiner Propheten gehört, die in deinem Auftrag zu unseren Königen, Fürsten und Vätern und zum ganzen Volk geredet haben." },
      { number: 7, text: "Du, Herr, bist im Recht, und wir stehen heute beschämt vor dir, wir alle, die Männer von Juda und die Bewohner von Jerusalem und alle Israeliten, ob sie in der Nähe oder in der Ferne sind, alle, die du wegen ihres Treuebruchs vertrieben und unter die Völker zerstreut hast." },
      { number: 8, text: "Jahwe, es muss uns die Schamröte ins Gesicht treiben, unseren Königen, Fürsten und Vätern, weil wir alle gegen dich gesündigt haben." },
      { number: 9, text: "Doch beim Herrn, unserem Gott, ist Erbarmen und Vergebung. Denn gegen ihn haben wir uns aufgelehnt." },
      { number: 10, text: "Wir haben nicht auf die Stimme von Jahwe, unserem Gott, gehört. Wir haben seine Befehle nicht befolgt, die er uns durch seine Diener vorgelegt hat, durch die Propheten." },
      { number: 11, text: "Ganz Israel hat deine Weisungen missachtet und deine Worte in den Wind geschlagen. Und so hat uns der Fluch getroffen, mit dem im Gesetz deines Dieners Mose jeder bedroht wird, der gegen dich sündigt." },
      { number: 12, text: "Gott hat seine Drohungen wahr gemacht, die er gegen uns ausgesprochen hatte und gegen die, die uns regierten: Er werde so schweres Unheil über uns bringen, dass es auf der ganzen Welt seinesgleichen sucht, – wie es jetzt in Jerusalem geschehen ist." },
      { number: 13, text: "Im Gesetz des Mose stand schon alles geschrieben, was nun als Unheil über uns gekommen ist. Und wir haben Jahwe, unseren Gott, nicht zur Gnade bewegt, indem wir von unserer Sünde umgekehrt wären und uns nach deiner Wahrheit gerichtet hätten." },
      { number: 14, text: "So hat Jahwe das Unheil absichtlich über uns hereinbrechen lassen, denn Jahwe, unser Gott, ist gerecht in allem, was er tut. Aber wir haben nicht auf ihn gehört." },
      { number: 15, text: "Aber du, Herr, unser Gott, bist es doch, der sein Volk aus Ägypten geführt und sich dadurch bis heute einen Namen gemacht hat: Ja, wir haben gesündigt, wir sind gottlos gewesen!" },
      { number: 16, text: "Herr, lass doch nach all den Beweisen deiner Gerechtigkeit deinen grimmigen Zorn nicht länger über deiner Stadt Jerusalem und dem Berg deines Heiligtums wüten. Denn wegen unserer Sünden und der Schuld unserer Väter sind Jerusalem und dein Volk zum Gespött aller Nachbarn geworden." },
      { number: 17, text: "Unser Gott, höre doch jetzt auf das Flehen deines Dieners und lass dein Gesicht wieder leuchten über deinem verwüsteten Heiligtum – um deinetwillen, Herr!" },
      { number: 18, text: "Mein Gott, neige doch dein Ohr und höre! Öffne deine Augen und schau dir die Verwüstung an und die Stadt, die nach deinem Namen genannt ist! Nicht im Vertrauen auf unsere Gerechtigkeit bringen wir unser Flehen vor dich, sondern im Vertrauen auf dein großes Erbarmen." },
      { number: 19, text: "Herr, höre! Herr, vergib! Herr, zögere nicht und greif ein! Lass uns nicht länger warten! Tu es um deinetwillen, mein Gott, denn deine Stadt und dein Volk sind doch nach deinem Namen genannt.\"" },
      { number: 20, text: "Während ich noch redete und betete und meine Sünde und die Sünde meines Volkes Israel bekannte und mein demütiges Gebet für Gottes heiligen Berg vor Jahwe, meinen Gott, brachte," },
      { number: 21, text: "während ich also noch beim Beten war, erreichte mich wie im raschen Flug der Mann Gabriel, den ich vorher in der Vision gesehen hatte. Es war zur Zeit des Abendopfers." },
      { number: 22, text: "Er öffnete mir das Verständnis. \"Daniel\", sagte er, \"ich bin jetzt losgezogen, um dir klare Einsicht zu geben." },
      { number: 23, text: "Schon zu Beginn deines Gebets erging ein Wort Gottes. So bin ich nun gekommen, es dir mitzuteilen, denn du genießt hohes Ansehen*. Gib acht auf das, was ich dir zu sagen habe, damit du die Vision verstehst!", footnotes: ["hohes Ansehen. Wörtlich: Du bist Kostbarkeiten."] },
      { number: 24, text: "Siebzig Jahrwochen* müssen vergehen, bis der Frevel zum Abschluss gebracht, die Macht der Sünde gebrochen und die Schuld gesühnt ist, bis eine ewige Gerechtigkeit herbeigeführt, die Prophetie endgültig bestätigt und der Höchstheilige* gesalbt ist.", footnotes: ["Siebzig Jahrwochen. Wörtlich: Siebzig Siebenheiten. Wahrscheinlich sind Jahre gemeint: 70 x 7 = 490 Jahre.", "Höchstheilige. Der Begriff kann sich auch auf den Tempel beziehen. Wahrscheinlich ist hier aber der Messias gemeint."] },
      { number: 25, text: "Du musst Folgendes wissen und verstehen: Vom Erlass des Befehls zum Wiederaufbau Jerusalems bis zu einem Gesalbten, einem Fürsten, vergehen sieben Jahrwochen*. 62 Jahrwochen lang wird es dann als wiederaufgebaute und befestigte Stadt bestehen bleiben*, auch wenn es schwere Zeiten erleben muss.", footnotes: ["sieben Jahrwochen. Wenn man von Jeremia 30,18 und 31,18ff ausgeht, ist das Ausgangsjahr 588/87 v.Chr. 49 Jahre später trat Kyrus auf, der in Jesaja 45,1 als Gesalbter Jahwes bezeichnet wird. – Andere Rechnungen gehen von Nehemia 2,1-8 aus. Dann wäre das Ausgangsjahr 444 v.Chr., was aber zu anderen Schwierigkeiten führt.", "bestehen bleiben. Der Ausgangspunkt der 434 Jahre (62 Jahrwochen) kann nur in der Zeit Nehemias liegen, wo der Wiederaufbau der Stadt vollendet wurde. Wenn wir dafür das Jahr 441 ansetzen, kommen wir in das Jahr 7 v.Chr., das Geburtsjahr von Jesus Christus."] },
      { number: 26, text: "Aber nach den 62 Jahrwochen wird ein Gesalbter die Todesstrafe erleiden und keine Hilfe finden.* Dann wird das Volk eines kommenden Fürsten die Stadt und das Heiligtum zerstören.* Das wird wie eine Überflutung sein. Und bis zum Ende wird es Krieg und Verwüstungen geben, wie Gott es beschlossen hat.", footnotes: ["Todesstrafe erleiden. Das bezieht sich dann auf die Kreuzigung von Jesus Christus.", "Zerstörung Jerusalems durch Titus, der später selbst Kaiser wurde."] },
      { number: 27, text: "Für eine Jahrwoche* wird der Fürst einen starken Bund mit den Vielen schließen. Doch in der Mitte der Jahrwoche wird er die Schlacht- und Speisopfer aufhören lassen.* Dazu wird er das Heiligtum verwüsten, indem er ein Gräuelbild dort aufstellt.* Schließlich wird die beschlossene Vernichtung auch ihn selbst treffen.", footnotes: ["Die 7. Jahrwoche könnte sich entweder auf die Zeit vom Beginn des Wirkens von Christus 27 n.Chr. bis zum Beginn der Mission 34 n.Chr. erstrecken, oder auf die Zeit des jüdisch-römischen Krieges (66-73 n.Chr.). In jedem Fall aber auch auf das Auftreten des Antichristus am Ende der Zeit.", "Speisopfer aufhören lassen. Das kann sich sowohl auf die Kreuzigung von Christus im Jahr 30 n.Chr. beziehen, nach der die Opfer im Tempel sinnlos wurden, als auch auf die Zerstörung Jerusalems und des Tempels, wonach die Opfer endgültig aufhörten.", "Gräuelbild dort aufstellt. Darauf spielt Jesus an, siehe Matthäus 24,15; Markus 13,14."] },
    ] },
    { number: 10, verses: [
      { number: 1, text: "Im dritten Regierungsjahr* des Perserkönigs Kyrus empfing Daniel, der auch Beltschazzar heißt, eine Botschaft Gottes. Was ihm darin offenbart wurde, ist wahr und betrifft einen großen Kampf. Daniel bemühte sich um Verständnis für die Botschaft und bekam es auch durch eine Vision. Er berichtet:", heading: "Ausblick auf die Zukunft", footnotes: ["dritten Regierungsjahr. 536/35 v.Chr. Daniel war 82 Jahre alt."] },
      { number: 2, text: "Damals trauerte ich, Daniel, drei Wochen lang." },
      { number: 3, text: "Ich verzichtete auf besondere Speisen, aß kein Fleisch, trank keinen Wein und pflegte mich nicht mit Salbölen bis die drei Wochen um waren." },
      { number: 4, text: "Am 24. April* stand ich am Ufer des großen Stroms, des Tigris,", footnotes: ["April. Wörtlich: des 1. Monats. Im Jahr 535 v.Chr."] },
      { number: 5, text: "und als ich aufblickte, sah ich einen Mann vor mir stehen. Er hatte ein Leinengewand an und war an den Hüften mit feinstem Gold umgürtet." },
      { number: 6, text: "Sein Körper glich einem Edelstein, sein Gesicht leuchtete wie ein Blitz und seine Augen brannten wie Fackeln. Seine Arme und Beine glänzten wie poliertes Kupfer und sein Reden klang wie das Tosen einer vielstimmigen Menschenmenge." },
      { number: 7, text: "Nur ich, Daniel, sah diese Erscheinung. Die Männer bei mir sahen nichts, sie wurden aber von einem so großen Schrecken gepackt, dass sie davonliefen und sich versteckten." },
      { number: 8, text: "So blieb ich allein zurück und sah diese gewaltige Erscheinung. Doch da verließ mich alle Kraft, das Blut wich aus meinem Gesicht und ich konnte mich kaum noch auf den Beinen halten." },
      { number: 9, text: "Und als ich ihn sprechen hörte, stürzte ich ohnmächtig zu Boden und blieb mit dem Gesicht auf der Erde liegen." },
      { number: 10, text: "Doch eine Hand rührte mich an und rüttelte mich hoch, so dass ich auf die Knie und Handflächen hochkam." },
      { number: 11, text: "\"Daniel\", sagte er zu mir, \"du bist hoch geschätzt bei Gott. Steh auf und höre, was ich dir zu sagen habe! Gott hat mich zu dir geschickt.\" Zitternd richtete ich mich auf." },
      { number: 12, text: "\"Hab keine Angst, Daniel!\", sagte er zu mir. \"Denn vom ersten Tag an, als du dich vor deinem Gott beugtest, um seinen Plan zu verstehen, hat er dein Gebet erhört. Und wegen deiner Worte bin ich gekommen." },
      { number: 13, text: "Aber der Engelfürst von Persien hat sich mir 21 Tage lang entgegengestellt. Da kam Michael, einer der höchsten Engelfürsten, mir zu Hilfe, so dass ich beim Kampf um Persien entbehrlich wurde." },
      { number: 14, text: "Nun bin ich hier, um dich darüber zu unterrichten, was mit deinem Volk am Ende der von Gott bestimmten Zeit geschehen wird. Denn wieder ist es eine Vision, die sich auf die letzte Zeit bezieht.\"" },
      { number: 15, text: "Als er so mit mir redete, blickte ich zu Boden und konnte kein Wort mehr herausbringen." },
      { number: 16, text: "Da berührte einer meine Lippen. Er sah aus wie ein Mensch. Nun konnte ich wieder sprechen. Ich sagte zu dem, der vor mir stand: \"Mein Herr, bei deiner Erscheinung wand ich mich in Schmerzen und verlor alle Kraft." },
      { number: 17, text: "Und wie soll dein Diener auch mit dir reden können, Herr? Mir fehlt seitdem ja alle Kraft, und selbst der Atem bleibt mir weg.\"" },
      { number: 18, text: "Da berührte mich der, der wie ein Mensch aussah, erneut und stärkte mich." },
      { number: 19, text: "\"Hab keine Angst!\", sagte er zu mir. \"Du bist hoch geschätzt bei Gott! Friede sei mit dir! Sei stark und fest!\" Als er so mit mir redete, fühlte ich mich gestärkt und sagte: \"Sprich nun, mein Herr! Jetzt hast du mir die Kraft dazu gegeben!\"" },
      { number: 20, text: "\"Weißt du nun, warum ich zu dir gekommen bin?\", sagte er. \"Schon bald werde ich wieder zum Fürsten von Persien zurückgehen, um weiter gegen ihn zu kämpfen. Und wenn ich mit ihm fertig geworden bin, muss ich auch gegen den Fürsten von Griechenland antreten." },
      { number: 21, text: "Doch vorher will ich dir mitteilen, was im Buch der Wahrheit aufgezeichnet ist. – Ja, es gibt niemand, der mit mir zusammen seine Kräfte gegen jene beiden aufbietet, außer Michael, eurem Fürst." },
      { number: 11, text: "Auch ich habe ihm einmal Hilfe und Schutz gegeben. Das war im ersten Regierungsjahr des Meders Darius.\"" },
    ] },
    { number: 11, verses: [
      { number: 2, text: "\"Aber jetzt will ich dir die Wahrheit mitteilen: Noch drei Könige werden in Persien auftreten; danach kommt ein vierter*, der reicher wird als alle seine Vorgänger. Wenn er durch seinen Reichtum dann zu großer Macht gekommen ist, wird er alles gegen das Reich der Griechen aufbieten.", heading: "Die große Geschichtsprophetie", footnotes: ["ein vierter. Xerxes I. (486-465 v.Chr.). Unter ihm stand Persien auf dem Gipfel seiner Macht."] },
      { number: 3, text: "Dann wird ein großer Held König* werden und mit großer Macht herrschen. Er wird durchsetzen, was er will.", footnotes: ["Held König. Offenbar ist Alexander der Große gemeint (336-323 v.Chr.)."] },
      { number: 4, text: "Doch auf dem Höhepunkt seiner Macht wird sein Reich zerbrochen und nach den vier Himmelsrichtungen zerteilt werden. Es fällt aber nicht seinen Nachkommen zu, und es ist auch nicht mehr so mächtig wie unter seiner Herrschaft. Denn sein Reich wird zerrissen und wird anderen gehören, die nicht mit ihm verwandt sind.*", footnotes: ["nicht mit ihm verwandt sind. Das erfüllte sich in den so genannten Diadochenreichen (siehe Fußnote zu Daniel 8,22)."] },
      { number: 5, text: "Und der König vom Süden* wird mächtig werden, aber einer seiner Generäle wird noch stärker werden als er und eine eigene Herrschaft* begründen, ein großes Reich.", footnotes: ["König vom Süden. Ptolemäus I. (323-283 v.Chr.) hatte sich zum Herrscher von Ägypten gemacht.", "eigene Herrschaft. Seleukos I. (vermutlich 312-281 v.Chr.), ein früherer General von Ptolemäus I., machte sich selbständig und errang die Herrschaft über Syrien."] },
      { number: 6, text: "Nach Ablauf einer Reihe von Jahren schließen sie dann ein Bündnis.* Die Tochter des Königs vom Süden* wird zum König vom Norden reisen, um ein Abkommen zu treffen. Doch sie kann ihren Einfluss nicht behaupten, und auch er wird nicht bestehen. Sie wird genauso sterben müssen wie ihr Vater und ihr Mann, die diese Verbindung gestiftet haben.", footnotes: ["Bündnis. Um 250 v.Chr. Allianz zwischen Ägypten und Syrien.", "Die Tochter von Ptolemäus II., Berenike, heiratete Antiochus II., der dafür seine Frau verstieß."] },
      { number: 7, text: "Doch ein Sprössling aus der gleichen Wurzel* wird an die Stelle ihres Vaters treten. Er wird den König vom Norden angreifen, in seine befestigte Hauptstadt* eindringen und ihm seine Macht demonstrieren.", footnotes: ["Sprössling aus der gleichen Wurzel. Berenikes Bruder Ptolemäus III. (246-221 v.Chr.).", "Hauptstadt. Entweder Seleuzia, die Hafenvorstadt, oder Antiochia selbst."] },
      { number: 8, text: "Er wird ihre Götter zusammen mit ihren gegossenen Bildwerken und den kostbaren Gefäßen und dazu Silber und Gold nach Ägypten schaffen. Dann wird er jedoch einige Jahre von ihm ablassen." },
      { number: 9, text: "Darauf wird der König vom Norden* in das Reich des Königs vom Süden einfallen, sich aber wieder in sein Land zurückziehen.", footnotes: ["König vom Norden. Das war Seleukos II. im Jahr 242 v.Chr."] },
      { number: 10, text: "Aber seine Söhne werden den Kampf aufnehmen und große Heeresmassen zusammenbringen. Diese Menge wird wie eine Sturmflut hereinbrechen und alles überfluten, sich aber wieder zurückziehen. Doch dann werden sie wieder rüsten und bis zu seiner Festung vorstoßen.*", footnotes: ["Dreimal griff Antiochus III. Ägypten an (221, 219 und 218 v.Chr.)."] },
      { number: 11, text: "Da wird der König vom Süden voller Wut gegen den König vom Norden kämpfen und ihn trotz seiner Übermacht besiegen.*", footnotes: ["besiegen. Ptolemäus IV. schlug Antiochus III. 217 v.Chr. in Raphia bei Gaza."] },
      { number: 12, text: "Doch wenn er die große Heeresmasse besiegt hat, wird er übermütig werden. Er wird Zehntausende fällen, aber seine Macht nicht lange behaupten." },
      { number: 13, text: "Denn einige Jahre später stellt der König vom Norden ein noch größeres Heer auf und rückt mit dieser riesigen Menge und großem Tross gegen ihn vor." },
      { number: 14, text: "In dieser Zeit werden sich noch viele andere gegen den König vom Süden erheben. Sogar aus deinem Volk werden sich gewalttätige Menschen erheben, um die Weissagung zu erfüllen. Aber sie werden scheitern." },
      { number: 15, text: "Dann wird der König vom Norden kommen und eine befestigte Stadt belagern und einnehmen.* Die Streitkräfte des Südens werden nicht standhalten können, nicht einmal ihre Elitetruppen sind stark genug, ihm zu widerstehen.", footnotes: ["einnehmen. Eroberung von Sidon durch Antiochus III."] },
      { number: 16, text: "Er kann machen, was er will, denn niemand leistet noch Widerstand. Auch im herrlichen Israel macht er sich breit und verwüstet das Land." },
      { number: 17, text: "Dann fasst er den Plan, das ganze Reich des Königs vom Süden in seine Gewalt zu bekommen. Er wird ihm eine seiner Töchter zur Frau geben*, um sein Reich zu verderben. Aber er wird sein Ziel nicht erreichen.", footnotes: ["zur Frau geben. Antiochus III. verheiratete seine Tochter Kleopatra 194 v.Chr. mit Ptolemäus V."] },
      { number: 18, text: "Schließlich wendet er sich gegen die Inseln und erobert viele von ihnen. Da wird ihm ein Heerführer entgegentreten und seinem Hohnlachen ein Ende bereiten; er wird es ihm so heimzahlen, dass ihm aller Übermut vergeht.*", footnotes: ["Übermut vergeht. Bei der Eroberung Kleinasiens und Teilen von Griechenland trat ihm der römische Feldherr Lucius Scipio 190 v.Chr. bei Magnesia entgegen und besiegte ihn. Antiochus III. werden schwere Tribute auferlegt."] },
      { number: 19, text: "Jetzt muss er anfangen, die Festungen seines eigenen Landes auszuplündern.* Doch dabei wird er stolpern und fallen und nicht mehr zu finden sein.", footnotes: ["auszuplündern. Um die Tribute zu bezahlen, plünderte Antiochus III. befestigte Städte und Tempel seines eigenen Landes. Dabei wurde er 187 v.Chr. getötet."] },
      { number: 20, text: "Sein Nachfolger wird einen Steuereintreiber durch Israel, die Zierde seines Reiches, schicken. Doch wird er schon nach kurzer Zeit getötet, aber nicht im Krieg und auch nicht im Zorn.*", footnotes: ["nicht im Zorn. Der Steuereintreiber Heliodor, Minister von Seleukos IV., lässt später seinen König hinterlistig ermorden."] },
      { number: 21, text: "An seine Stelle wird ein niederträchtiger Mensch treten, der keinen Anspruch auf das Königtum hat, es aber durch Intrigen an sich reißt.*", footnotes: ["durch Intrigen an sich reißt. Der aalglatte Antiochus IV. war nicht als Thronfolger vorgesehen, schaffte es aber mit Hilfe von König Eumenes II. von Pergamon, den syrischen Thron zu besteigen."] },
      { number: 22, text: "Ganze Heere werden vor ihm weggeschwemmt und vernichtet werden, ja selbst ein Oberhaupt des Bundes.*", footnotes: ["... Bundes. Das erfüllt sich an dem Hohen Priester Onias III., der 175 v.Chr. von Antiochus IV. abgesetzt und 171 v.Chr. ermordet wurde."] },
      { number: 23, text: "Und nachdem er sich mit ihm verbündet hat, hintergeht er ihn. Nur mit einer kleinen Truppe wird er die Macht erringen." },
      { number: 24, text: "Mitten im Frieden wird er in die reichsten Landstriche einer Provinz eindringen und tun, was keiner seiner Vorgänger je getan hat: Er raubt sie aus und verteilt die Beute verschwenderisch unter seine Gefolgsleute. Seine Pläne richten sich auch gegen befestigte Städte, allerdings nur eine Zeit lang." },
      { number: 25, text: "Dann bietet er seine ganze Kraft und seinen ganzen Mut auf und zieht mit einem großen Heer gegen den König vom Süden, der ebenfalls ein großes und überaus starkes Heer gegen ihn aufstellen wird. Doch er wird nicht vor ihm standhalten, weil man Intrigen gegen ihn spinnt." },
      { number: 26, text: "Seine engsten Vertrauten stürzen ihn, sein Heer zerstreut sich und viele finden den Tod." },
      { number: 27, text: "Die beiden Könige sitzen dann am selben Tisch zusammen und versuchen sich gegenseitig hinters Licht zu führen. Doch ihre Pläne gelingen nicht, weil die Zeit für das Ende noch nicht gekommen ist." },
      { number: 28, text: "Der König vom Norden wird mit großer Beute in sein Land zurückkehren. Doch sein Sinn ist gegen den heiligen Bund* gerichtet. Er handelt auch entsprechend* und kehrt schließlich in sein Land zurück.", footnotes: ["heiligen Bund. Das meint das Volk, mit dem Gott einen heiligen Bund geschlossen hat, also Israel.", "handelt auch entsprechend. Antiochus IV. marschierte auf der Rückreise gegen Jerusalem, richtete dort ein Blutbad an, betrat den Tempel und plünderte ihn. Er war offenbar ein Vorläufer des endzeitlichen Antichristus."] },
      { number: 29, text: "Zu einer von Gott bestimmten Zeit wird er wieder in den Süden ziehen. Doch diesmal wird es nicht so enden wie beim ersten Mal." },
      { number: 30, text: "Es werden nämlich Schiffe aus dem Westen kommen und ihn bedrohen.* Da wird er den Mut verlieren und umkehren. Seinen Zorn aber wird er an dem heiligen Bund auslassen und sich mit denen verbünden, die diesem Bund den Rücken kehren.", footnotes: ["ihn bedrohen. Kurz vor Alexandria trat 168 v.Chr. eine römische Gesandtschaft Antiochus IV. entgegen und forderte ihn ultimativ zur Umkehr auf."] },
      { number: 31, text: "Dann stellt er Streitkräfte auf, die das befestigte Heiligtum entweihen. Sie werden das regelmäßige Opfer abschaffen und das entsetzliche Scheusal* dort aufstellen.", footnotes: ["das entsetzliche Scheusal. Der Brandopferaltar wurde von Antiochus IV. zum Zeusaltar gemacht. Es könnte sogar sein, dass er ein Zeusbild, das seine eigenen Züge trug, im Tempel aufstellte."] },
      { number: 32, text: "Der König wird die, die sich gegen den Bund vergangen haben, durch glatte Worte zu Gottlosen machen. Aber das Volk, das seinen Gott kennt, wird standhaft bleiben und entsprechend handeln." },
      { number: 33, text: "Und die Verständigen* im Volk bringen viele zur Einsicht. Dafür werden sie eine Zeit lang mit Feuer und Schwert verfolgt, kommen ins Gefängnis und verlieren ihren Besitz.", footnotes: ["Verständigen. Menschen, die im Gesetz geschult sind und Gott aufrichtig dienen."] },
      { number: 34, text: "Doch während dieser Zeit erfahren sie auch ein wenig Hilfe. Allerdings schließen sich ihnen viele nur zum Schein an." },
      { number: 35, text: "Und auch von ihnen selbst werden einige zugrunde gehen. So sollen die Verständigen bis zur Zeit des Endes geprüft, geläutert und gereinigt werden, denn es dauert noch eine Weile bis zu dieser bestimmten Zeit." },
      { number: 36, text: "Der König aber wird machen, was er will. Er wird übermütig werden und sich einbilden, er sei mächtiger als alle Götter. Selbst gegen Gott, der über allen Göttern steht, wird er Ungeheuerliches reden. Und er wird Erfolg haben, so lange Gott es im Zorn über sein Volk zulässt, denn alles geschieht genau nach seinem fest beschlossenen Plan." },
      { number: 37, text: "Selbst die Götter seiner Väter und den Lieblingsgott der Frauen wird er missachten wie jeden anderen Gott. Denn er bildet sich ein, über allen zu stehen." },
      { number: 38, text: "Stattdessen verehrt er den Gott der Festungen*, den seine Vorfahren nicht kannten. Ihn wird er mit Gold und Silber, mit Edelsteinen und Kostbarkeiten ehren.", footnotes: ["Gott der Festungen. Entweder meint das einen Gott, der Macht über Festungen verleiht, oder militärische Macht an sich."] },
      { number: 39, text: "Mit seiner Hilfe wird er starke Festungen zu Fall bringen. Wer seinen Gott anerkennt, den überhäuft er mit Ehren, lässt ihn über viele Menschen herrschen und gibt ihm ganze Ländereien als Lohn.\"" },
      { number: 40, text: "\"Zur Zeit des Endes wird der König vom Süden* mit ihm zusammenstoßen, aber der König vom Norden wird mit Streitwagen, Reitern und vielen Schiffen gegen ihn anstürmen. Wie eine verheerende Flut wird er die Länder überschwemmen.", heading: "Am Ende der Zeit", footnotes: ["König vom Süden. Es scheint, dass die Prophetie hier nicht mehr auf Antiochus IV. zielt, sondern entweder den Einbruch der römischen Weltmacht schildert oder noch stärker als alles Vorhergehende den letzten Abschnitt der irdischen Geschichte im Blick hat."] },
      { number: 41, text: "Er wird auch in das herrliche Land Israel eindringen, und viele werden dort umkommen. Nur die Edomiter, die Moabiter und ein Großteil der Ammoniter werden verschont." },
      { number: 42, text: "Er wird seine Hand nach weiteren Ländern ausstrecken, und Ägypten kann sich nicht vor seinem Zugriff retten." },
      { number: 43, text: "Er wird sich aller seiner goldenen und silbernen Schätze und seiner sonstigen Kostbarkeiten bemächtigen. Libyer und Nubier werden dabei in seinem Gefolge sein." },
      { number: 44, text: "Dann aber werden ihn Gerüchte aus dem Osten und Norden erschrecken. Wutentbrannt wird er losziehen, um so viel wie möglich von seinen Feinden und ihren Gütern zu vernichten.*", footnotes: ["vernichten. Wörtlich: den Bann zu vollstrecken"] },
      { number: 45, text: "Und gerade wenn er seine Prunkzelte zwischen dem Meer und dem Berg Zion aufgeschlagen hat, wird das Ende für ihn kommen, und niemand kann ihm helfen." },
    ] },
    { number: 12, verses: [
      { number: 1, text: "In dieser Zeit wird der große Engelsfürst Michael auftreten, der dein Volk beschützt. Denn es wird eine Zeit der Bedrängnis sein, wie es sie seit Menschengedenken noch nie gegeben hat. Doch dein Volk wird gerettet werden, und zwar jeder, der im Buch Gottes aufgenommen ist." },
      { number: 2, text: "Und viele von denen, die in der Erde ruhen, werden erwachen: die einen zum ewigen Leben und die anderen zur Schande, zur ewigen Abscheu." },
      { number: 3, text: "Doch die Verständigen werden leuchten wie der strahlende Himmel; und die, die vielen anderen zur Gerechtigkeit* verholfen haben, werden glänzen wie die Sterne, immer und ewig.", footnotes: ["Das meint die Gerechtigkeit, die vor Gott Bestand hat, wie ein Vergleich mit Jesaja 53,11 zeigt."] },
      { number: 4, text: "Aber du, Daniel, bewahre die Worte zuverlässig auf und versiegle das Buch* bis zur Zeit des Endes. Viele werden darin forschen und das Verständnis wird zunehmen.\"", footnotes: ["versiegle das Buch. Offenbar sollte er wie Jeremia 32,10ff ein Original aufbewahren, aber gleichzeitig offene Abschriften davon zugänglich machen."] },
      { number: 5, text: "Als ich, Daniel, mich nun umschaute, sah ich zwei andere Engel dastehen, einer auf dieser und der andere auf jener Seite des Stromes*.", footnotes: ["Strom. Es handelt sich wie in Kapitel 10,4 um den Tigris."] },
      { number: 6, text: "Einer von ihnen fragte den in Leinen gekleideten Mann, der über dem Wasser des Stromes stand: \"Wie lange dauert es noch, bis diese erstaunlichen Vorgänge ein Ende haben?\"" },
      { number: 7, text: "Der Mann über dem Wasser erhob beide Hände zum Himmel und schwor bei Gott, der ewig lebt: \"Es dauert eine Zeit, zwei Zeiten und eine halbe Zeit*. Und wenn die Kraft des heiligen Volkes zerschlagen ist, wird sich das alles vollenden.\"", footnotes: ["Zeit. Siehe Anmerkung zu Daniel 7,25."] },
      { number: 8, text: "Ich hörte es, verstand es aber nicht. Deshalb fragte ich: \"Mein Herr, wie wird das alles ausgehen?\"" },
      { number: 9, text: "Doch er sagte: \"Geh jetzt, Daniel! Denn die Worte sollen bis zum Ende aufbewahrt und versiegelt bleiben." },
      { number: 10, text: "Viele Menschen werden geprüft, gereinigt und geläutert werden. Die Gottlosen werden weiter gottlos handeln, aber von ihnen wird es niemand verstehen. Doch die Verständigen werden es begreifen." },
      { number: 11, text: "Wenn das tägliche Opfer abgeschafft und das entsetzliche Scheusal aufgestellt wird – von dem Zeitpunkt an sind es 1290 Tage.*", footnotes: ["1290 Tage. Die Differenz zu den 1335 Tagen von V. 12 bilden offenbar eine Übergangszeit von 45 Tagen zwischen der Zerschlagung Israels und der Aufrichtung des göttlichen Reiches."] },
      { number: 12, text: "Glücklich, wer es aushält und 1335 Tage erreicht!" },
      { number: 13, text: "Aber du, geh deinen Weg bis zum Ende! Du wirst dich zur Ruhe legen und am Ende der Zeit auferstehen, um dein Erbe in Empfang zu nehmen.\"" },
    ] },
  ],
};